### Clase `StoreManager`

```java
import java.util.LinkedList;
import java.util.Queue;

public class StoreManager {
    private LinkedList<Order> returnOrders;
    private Queue<Product> soldProducts;

    // Constructor
    public StoreManager() {
        this.returnOrders = new LinkedList<>();
        this.soldProducts = new LinkedList<>();
    }

    // Getters y Setters
    public LinkedList<Order> getReturnOrders() {
        return returnOrders;
    }

    public void setReturnOrders(LinkedList<Order> returnOrders) {
