```java
import java.awt.Point;

public class Triangle extends Figure {
    private Point vertex1;
    private Point vertex2;
    private Point vertex3;

    // Constructor
    public Triangle(String name, Point vertex1, Point vertex2, Point vertex3) {
        super(name);
        this.vertex1 = vertex1;
        this.vertex2 = vertex2;
        this.vertex3 = vertex3;
    }

    // Implementa el método area() que calcule el área del triángulo
    @Override
    public double area() {
        double Ax = vertex1.getX();
        double Ay = vertex1.getY();
        double Bx = vertex2.getX();
        double By = vertex2.getY();
        double Cx = vertex3.getX();
        double Cy = vertex3.getY();
        return 0.5 * Math.abs(Ax * (By - Cy) + Bx * (Cy - Ay) + Cx * (Ay - By));
    }

    // Implementa el método isRegular() que indique si el triángulo es regular
    @Override
    public boolean isRegular() {
        double side1 = vertex1.distance(vertex2);
        double side2 = vertex2.distance(vertex3);
        double side3 = vertex3.distance(vertex1);
        return side1 == side2 && side2 == side3;
    }

    // Sobreescribe el método toString() para que devuelva el nombre de la figura, y sus vértices
    @Override
    public String toString() {
        return "Triangle[name=" + getName() + ", vertex1=" + vertex1 + ", vertex2=" + vertex2 + ", vertex3=" + vertex3 + "]";
    }

    // Métodos get y set para los vértices
    public Point getVertex1() {
        return vertex1;
    }

    public void setVertex1(Point vertex1) {
        this.vertex1 = vertex1;
    }

    public Point getVertex2() {
        return vertex2;
    }

    public void setVertex2(Point vertex2) {
        this.vertex2 = vertex2;
    }

    public Point getVertex3() {
        return vertex3;
    }

    public void setVertex3(Point vertex3) {
        this.vertex3 = vertex3;
    }
}
```

### Explicación:

