### _Modelado de Clases_

A continuación, se muestra un ejemplo de cómo podrías modelar la clase `Product` y la clase `ProductList`:

#### Clase `Product`

```java
public class Product {
    private String id;
    private String name;
    private double cost;
    private double price;
    private char category;

    // Constructor vacío
    public Product() {
    }

    // Constructor con parámetros
    public Product(String id, String name, double cost, double price, char category) {
        this.id = id;
        this.name = name;
        this.cost = cost;
        this.price = price;
        setCategory(category);
    }

    // Métodos de acceso y modificación (get/set)
    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public double getCost() {
        return cost;
    }

    public void setCost(double cost) {
        this.cost = cost;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    public char getCategory() {
        return category;
    }

    public void setCategory(char category) {
        if (category == 'f' || category == 's' || category == 'e' || category == 'm') {
            this.category = category;
        } else {
            throw new IllegalArgumentException("Invalid category. Must be 'f', 's', 'e', or 'm'.");
        }
    }

    // Método set que recibe un array de Strings
    public void set(String[] data) {
        if (data.length != 5) {
            throw new IllegalArgumentException("Invalid data length. Must be 5.");
        }
        setId(data[0]);
        setName(data[1]);
        setCost(Double.parseDouble(data[2]));
        setPrice(Double.parseDouble(data[3]));
        setCategory(data[4].charAt(0));
    }

    // Método toString
    @Override
    public String toString() {
        return id + "\\|" + name + "\\|" + cost + "\\|" + price + "\\|" + category;
    }

    // Método print
    public void print() {
        System.out.println(toString());
    }

    // Método writeToFile
    public void writeToFile() {
        // Implementar lógica para escribir en fichero
    }

    // Método readFromStdio
    public static Product readFromStdio() {
        // Implementar lógica para leer desde la entrada estándar
        return new Product();
    }

    // Método readFromFile
    public static Product readFromFile(String file) {
        // Implementar lógica para leer desde un fichero
        return new Product();
    }
}
```

#### Clase `ProductList`

```java
import java.util.ArrayList;
import java.util.List;

public class ProductList {
    private List<Product> products;

    public ProductList() {
        products = new ArrayList<>();
    }

    public void addProduct(Product product) {
        products.add(product);
    }

    public void removeProduct(Product product) {
        products.remove(product);
    }

    public double calculateCost() {
        double totalCost = 0;
        for (Product product : products) {
            totalCost += product.getCost();
        }
        return totalCost;
    }

    public double calculatePrice() {
        double totalPrice = 0;
        for (Product product : products) {
            totalPrice += product.getPrice();
        }
        return totalPrice;
    }

    public double calculateBenefit() {
        return calculatePrice() - calculateCost();
    }

    public Product mostExpensiveProduct() {
        Product mostExpensive = null;
        for (Product product : products) {
            if (mostExpensive == null || product.getPrice() > mostExpensive.getPrice()) {
                mostExpensive = product;
            }
        }
        return mostExpensive;
    }

    public Product cheapestProduct() {
        Product cheapest = null;
        for (Product product : products) {
            if (cheapest == null || product.getPrice() < cheapest.getPrice()) {
                cheapest = product;
            }
        }
        return cheapest;
    }
}
```

