    FigureSet figures = new FigureSet();

    Circule c = new Circule("Circ1", new Point(2, 3), 4);
    figures.addFigure(c);
    Triangle t = new Triangle("Tri1", new Point(4,5), new Point(-9,5), new Point(8,-7));
    figures.addFigure(t);
}
```

