//2023_GITT_Parcial1_

//Apartado1

public interface Taxableproducts {
    public static final int GENERAL = 21;
    public static final int REDUCED = 10;
    public static final int SUPEREDUCED = 5;

    public double taxes();
    public int taxRate();
}

public abstract class Product implements Taxableproducts {
    private static final char FOOD = 'f';
    private static final char SUPPLIES = 's';
    private static final char EQUIPMENTS = 'e';
    private static final char MISCELLANY = 'm';
    private char category;

    public Product(char category) {
        setCategory(category);
    }

    public abstract double taxes();

    public int taxRate() {
        if (category == SUPPLIES) {
            return Taxableproducts.REDUCED;
        } else if (category == FOOD) {
            return Taxableproducts.SUPEREDUCED;
        } else {
            return Taxableproducts.GENERAL;
        }
    }

    public void setCategory(char category) {
        if ((category == FOOD) || (category == SUPPLIES) || (category == EQUIPMENTS) || (category == MISCELLANY)) {
            this.category = category;
        } else {
            System.out.println("Error en el valor de category");
        }
    }
}

public class StockableProduct extends Product {
    private static int PID_CONT = 0;
    private String productID;
    private double pricePerUnit;

    public StockableProduct(double pricePerUnit, char category) {
        super(category);
        this.pricePerUnit = pricePerUnit;
        PID_CONT++;
        this.productID = "PID" + PID_CONT;
    }

    public double taxes() {
        return (taxRate() * this.pricePerUnit) / 100;
    }
}
```

### **Correcciones realizadas:**

1. **Error de sintaxis**: Se corrigió la comilla faltante en el método `setCategory`.
2. **Implementación de la interfaz**: La clase `Product` ahora implementa correctamente la interfaz `Taxableproducts`.
