        MyLinkedList list = new MyLinkedList();

        // Inicializar la lista con diez elementos de valor 1
        for (int i = 0; i < 10; i++) {
            list.insert(1);
        }

        // Insertar un elemento con valor 0 en la cuarta posición
        list.insertAtPosition(0, 4);

        // Imprimir la lista
        list.printList();
    }
}

// Método adicional en MyLinkedList para insertar en una posición específica
public void insertAtPosition(int data, int position) {
    Node newNode = new Node(data);
    if (position == 1) {
        newNode.next = head;
        head = newNode;
        return;
    }
    Node temp = head;
    for (int i = 1; i < position - 1 && temp != null; i++) {
        temp = temp.next;
    }
    if (temp != null) {
        newNode.next = temp.next;
        temp.next = newNode;
    }
}
```

