        Node<E> newNode = new Node<>(data);
        if (isEmpty()) {
            head = newNode;
        } else {
            tail.next = newNode;
        }
        tail = newNode;
        size++;
    }

    @Override
    public E front() {
        if (isEmpty()) {
            return null; // O lanzar una excepción
        }
        return head.data;
    }

    @Override
    public E dequeue() {
        if (isEmpty()) {
            return null; // O lanzar una excepción
        }
        E data = head.data;
        head = head.next;
        size--;
        if (isEmpty()) {
            tail = null;
        }
        return data;
    }
}
```

