    public double getY() {
        return y;
    }

    public void setX(double x) {
        this.x = x;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double distanceToOrigin() {
        Point origin = new Point(0.0, 0.0);
        return this.distance(origin);
    }

    public double distance(Point other) {
        double dx = this.x - other.x;
        double dy = this.y - other.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    public Point nearestPoint(Point[] otherPoints) {
        if (otherPoints == null || otherPoints.length == 0) {
            return null;
        }
        Point nearest = otherPoints[0];
        double miniDistance = this.distance(nearest);

        for (int i = 1; i < otherPoints.length; i++) {
            double distance = this.distance(otherPoints[i]);
            if (miniDistance > distance) {
                miniDistance = distance;
                nearest = otherPoints[i];
            }
        }
        return nearest;
    }

    public int quadrant() {
        if (x == 0 && y == 0) {
            return 0;
        } else if (x > 0.0 && y > 0.0) {
            return 1;
        } else if (x < 0.0 && y > 0.0) {
            return 2;
        } else if (x < 0.0 && y < 0.0) {
            return 3;
        } else if (x > 0.0 && y < 0.0) {
            return 4;
        }
        return -1;
    }
}
```

### Explanation:

- **setX Method**: The `setX` method now accepts a `double` argument to set the `x` coordinate.
- **setY Method**: The `setY` method now accepts a `double` argument to set the `y` coordinate.
- **distanceToOrigin Method**: Fixed the recursion issue by directly calling the `distance` method.

