        } else {
            p = new Point(3.0, 4.0);
        }
    }

    @Test
    void testDefaultGetX() {
        specialSetup = false;
        setUp();
        assertEquals(3.0, p.getX());
    }

    @Test
    void testSpecialGetX() {
        specialSetup = true;
        setUp();
        assertEquals(5.0, p.getX());
    }
}
```

