### Approach 2: Using `@Nested` Test Classes

```java
package Lab6;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

class PointTest {

    @Nested
    class DefaultSetupTests {
        private Point p;

        @BeforeEach
        void setUp() {
            p = new Point(3.0, 4.0);
        }

        @Test
        void testGetX() {
            assertEquals(3.0, p.getX());
        }

        @Test
        void testGetY() {
            assertEquals(4.0, p.getY());
        }

        @Test
        void testToString() {
            assertEquals("The quadrant is: 1. The Point is: (3.0, 4.0)", p.toString());
        }

        @Test
        void testDistanceToOrigin() {
            assertEquals(5.0, p.distanceToOrigin(), 0.001);
        }

        @Test
        void testDistance() {
            Point p2 = new Point(6.0, 8.0);
            assertEquals(5.0, p.distance(p2), 0.001);
        }

        @Test
        void testNearestPoint() {
            Point[] points = {
                new Point(6.0, 8.0),
                new Point(2.0, 3.0),
                new Point(5.0, 5.0)
            };
            Point nearest = p.nearestPoint(points);
            assertEquals(2.0, nearest.getX());
            assertEquals(3.0, nearest.getY());
        }

        @Test
        void testQuadrant() {
            assertEquals(1, p.quadrant());
        }
    }

    @Nested
    class SpecialSetupTests {
        private Point p;

        @BeforeEach
        void setUp() {
            p = new Point(5.0, 6.0);
        }

        @Test
        void testGetX() {
            assertEquals(5.0, p.getX());
        }

        @Test
        void testGetY() {
            assertEquals(6.0, p.getY());
        }

        @Test
        void testToString() {
            assertEquals("The quadrant is: 1. The Point is: (5.0, 6.0)", p.toString());
        }

        @Test
        void testDistanceToOrigin() {
            assertEquals(Math.sqrt(61.0), p.distanceToOrigin(), 0.001);
        }

        @Test
        void testDistance() {
            Point p2 = new Point(8.0, 10.0);
            assertEquals(Math.sqrt(18.0), p.distance(p2), 0.001);
        }

        @Test
        void testNearestPoint() {
            Point[] points = {
                new Point(8.0, 10.0),
                new Point(4.0, 5.0),
                new Point(7.0, 7.0)
            };
            Point nearest = p.nearestPoint(points);
            assertEquals(4.0, nearest.getX());
            assertEquals(5.0, nearest.getY());
        }

        @Test
        void testQuadrant() {
            assertEquals(1, p.quadrant());
        }
    }
}
```

### Explanation:

- **`@Nested` Test Classes**: The `DefaultSetupTests` and `SpecialSetupTests` classes each have their own `@BeforeEach` method to set up the `Point` object with different values.
- **Separate Setup**: Each nested class has its own setup logic, ensuring that tests within each class use the correct setup.
- **Test Methods**: Each test method within the nested classes uses the `Point` object initialized by the respective `@BeforeEach` method.

### Conclusion:

Both approaches allow you to handle different setup requirements for different test cases. The conditional logic approach uses a single `@BeforeEach` method with flags to determine the setup, while the nested test classes approach organizes tests into groups, each with its own setup logic.

