        System.out.println("Lista después de extraer el nodo siguiente a 'b':");
        list.print();

        // Tamaño de la lista
        System.out.println("Tamaño de la lista: " + list.size());

        // Buscar nodo por información
        System.out.println("Buscar nodo con información 'a': " + list.searchNode("a"));

        // Buscar nodo por posición
        System.out.println("Buscar nodo en posición 1: " + list.searchNode(1));

        // Buscar último nodo
        System.out.println("Último nodo: " + list.searchLastNode());

