public interface CandleCounter {
    String getImplementationDescription();
    long count(long years);
}

// CandleCounterIterative.java
public class CandleCounterIterative implements CandleCounter {

    @Override
    public String getImplementationDescription() {
        return "Iterative";
    }

    @Override
    public long count(long years) {
        long totalCandles = 0;
        for (long i = 1; i <= years; i++) {
            totalCandles += i;
        }
        return totalCandles;
    }

    public static void main(String[] args) {
        CandleCounterTest.test(new CandleCounterIterative());
    }
}

// CandleCounterTest.java
public class CandleCounterTest {

    public static void test(CandleCounter counter) {
        System.out.println("Testing " + counter.getImplementationDescription() + ":");

        long[] testYears = {0, 1, 2, 6, 10, 1000};
        long[] expectedResults = {0, 1, 3, 21, 55, 500500};

        for (int i = 0; i < testYears.length; i++) {
            long result = counter.count(testYears[i]);
            System.out.println("count(" + testYears[i] + "): " + result + ", " + (result == expectedResults[i] ? "OK" : "FAIL"));
        }
    }

    public static void main(String[] args) {
        test(new CandleCounterIterative());
        // Uncomment the following lines to test other implementations later
