public class MyAdvancedLinkedList<E> extends MyBasicLinkedList<E>{

	public MyAdvancedLinkedList() {
		super();
	}

	public void insert(E info, int position) {
		 if (position < 0) return;
	        if (position == 0) {
	            insert(info);
	            return;
	        }
	        Node<E> previous = searchNode(position - 1);
	        Node<E> n = new Node<>(info);
	        if (previous != null) {
	        	insert(info, n);
	        }

	}

	public E extract(int position) {
		Node<E> previous = searchNode(position - 1);
		E info = null;
		if(previous != null) {
			info = extract(previous);
		}
		return info;
	}

	public void insertLast(E info) {
		Node<E> ln = searchLastNode();
		if(ln != null) {
			insert(info, ln);
		}else {
			this.head = new Node<E>(info);
		}
	}

	public E removeLast() {
		E info = null;
		Node<E> current = this.head;
		int listSize = size();
		if(!isEmpty()) {
			if(listSize == 1) {
				info = current.getInfo();
				this.head = null;
			}else {
				Node<E> prevLastNode = searchNode(listSize - 2);
				info = extract(prevLastNode);
			}
		}
		return info;
	}

	public void print(int position) {
		Node<E> current = this.head;
		int count = 0;
		String text = "";
		if(!isEmpty()) {
			while(current != null && count < position) {
				current = current.getNext();
				count++;
			}
			while(current != null) {
				text = text + current.getClass().toString();
				if (current.getNext()!= null) {
					text = text + " -> ";
				}
				current = current.getNext();
			}
		}
		System.out.println(text);
	}

}
