    // Constructor
    public MyAdvancedLinkedList() {
        super();
    }

    // Method to insert a node at a specific position
    public void insert(E info, int position) {
        if (position < 0) return;
        if (position == 0) {
            insertFirst(info);
            return;
        }
        Node<E> previous = getNode(position - 1);
        if (previous == null) return;
        Node<E> newNode = new Node<>(info);
        newNode.setNext(previous.getNext());
        previous.setNext(newNode);
    }

    // Method to extract a node from a specific position
    public E extract(int position) {
        if (position < 0) return null;
        if (position == 0) {
            return extractFirst();
        }
        Node<E> previous = getNode(position - 1);
        if (previous == null || previous.getNext() == null) return null;
        Node<E> toRemove = previous.getNext();
        previous.setNext(toRemove.getNext());
        return toRemove.getInfo();
    }

    // Method to insert a node at the end of the list
    public void insertLast(E info) {
        if (first == null) {
            insertFirst(info);
            return;
        }
        Node<E> last = getLastNode();
        Node<E> newNode = new Node<>(info);
        last.setNext(newNode);
    }

    // Method to remove the last node of the list
    public E removeLast() {
        if (first == null) return null;
        if (first.getNext() == null) {
            return extractFirst();
        }
        Node<E> previous = getNode(size() - 2);
        Node<E> last = previous.getNext();
        previous.setNext(null);
        return last.getInfo();
    }

    // Method to print the list from a specific position
    public void print(int position) {
        if (position < 0) return;
        Node<E> current = getNode(position);
        while (current != null) {
            System.out.print(current.getInfo());
            if (current.getNext() != null) {
                System.out.print(" -> ");
            }
            current = current.getNext();
        }
        System.out.println();
    }

    // Helper method to get the node at a specific position
    private Node<E> getNode(int position) {
        if (position < 0) return null;
        Node<E> current = first;
        for (int i = 0; i < position && current != null; i++) {
            current = current.getNext();
        }
        return current;
    }

    // Helper method to get the last node
    private Node<E> getLastNode() {
        Node<E> current = first;
        while (current.getNext() != null) {
            current = current.getNext();
        }
        return current;
    }
}
