m.question:
tengo ya una clase llamada LinkedQueue impleentada, hay que hacerlo con eso. "public class LinkedQueue<E> implements Queue<E>{

	private Node<E> head;
	private Node<E> tail;
	private int size;

	public LinkedQueue() {
		this.head = null;
		this.tail = null;
		this.size = 0;
	}

	@Override
	public boolean isEmpty() {
		return head==null;
	}

	@Override
	public int size() {
		return size;
	}

	@Override
	public void enqueue(E info) {
		Node<E> n = new Node(info, null);
		if(isEmpty()) {
			head = n;
		}else {
			tail.setNext(n);
		}
		tail = n;
		size++;
	}

	@Override
	public E dequeue() {
		E info;
		if(isEmpty()) {
			info = null;
		}else {
			info = head.getInfo();
			head = head.getNext();
			size--;
			if(isEmpty()) {
				tail = null;
			}
		}
		return info;
	}

	@Override
	public E front() {
		if(isEmpty()) {
			return null;
		}else {
			return head.getInfo();
		}
	}

}"

