        if (args.length < 4 || args.length % 2 != 0) {
            System.out.println("Uso: java TestPoint <x1> <y1> <x2> <y2> ... <xn> <yn>");
            return;
        }

        try {
            // Parsear los primeros dos argumentos a double para el primer punto
            double x1 = Double.parseDouble(args[0]);
            double y1 = Double.parseDouble(args[1]);

            // Crear el primer objeto Point
            Point point1 = new Point(x1, y1);

            // Calcular el número de puntos adicionales
            int numPoints = (args.length - 2) / 2;
            Point[] otherPoints = new Point[numPoints];

            // Crear los otros puntos con los argumentos restantes
            for (int i = 0; i < numPoints; i++) {
                double x = Double.parseDouble(args[2 + 2 * i]);
                double y = Double.parseDouble(args[3 + 2 * i]);
                otherPoints[i] = new Point(x, y);
            }

            // Imprimir la representación textual del primer punto
            System.out.println("Punto 1: " + point1.toString());

            // Imprimir la representación textual de los otros puntos
            for (int i = 0; i < numPoints; i++) {
                System.out.println("Punto " + (i + 2) + ": " + otherPoints[i].toString());
