```java
public class LBSNode<E> implements Comparable<LBSNode<E>> {
    private E info;
    private Comparable key;
    private BSTree<E> right;
    private BSTree<E> left;

    public LBSNode(Comparable key, E info, BSTree<E> left, BSTree<E> right) {
        this.info = info;
        this.key = key;
        this.right = right;
        this.left = left;
    }

    public E getInfo() {
        return info;
    }

    public void setInfo(E info) {
        this.info = info;
    }

    public Comparable getKey() {
        return key;
    }

    public void setKey(Comparable key) {
        this.key = key;
    }

    public BSTree<E> getLeft() {
        return left;
    }

    public void setLeft(BSTree<E> left) {
        this.left = left;
    }

    public BSTree<E> getRight() {
        return right;
    }

    public void setRight(BSTree<E> right) {
        this.right = right;
    }

    @Override
    public String toString() {
        if (info != null) {
            return info.toString();
        } else {
            return "";
        }
    }

    @Override
    public int compareTo(LBSNode<E> o) {
        if (this.key == null || o.key == null) {
            throw new NullPointerException("Keys cannot be null");
        }
        return this.key.compareTo(o.key);
    }
}
```

