import java.util.Random;

public class StudentDAOMock implements StudentDAOApi {
    private Student[] students;

    public StudentDAOMock() {
        Random random = new Random();
        students = new Student[2];
        students[0] = new Student("Student1", random.nextFloat() * 10);
        students[1] = new Student("Student2", random.nextFloat() * 10);
    }

    @Override
    public Student[] findAll() {
        return students;
    }

    @Override
    public float minNota() {
        float min = Float.MAX_VALUE;
        for (Student student : students) {
            if (student.getNota() < min) {
                min = student.getNota();
            }
        }
        return min;
    }

    @Override
    public float maxNota() {
        float max = Float.MIN_VALUE;
        for (Student student : students) {
            if (student.getNota() > max) {
                max = student.getNota();
            }
        }
        return max;
    }

    @Override
    public float avgNota() {
        float sum = 0;
        for (Student student : students) {
            sum += student.getNota();
        }
        return sum / students.length;
    }
}
```

