Claro, aquí tienes la implementación de la clase `BinOperations` que implementa la interfaz `BinConverter` con los métodos `int2bin` y `bin2int` utilizando recursión:

```java
public interface BinConverter {
    public String int2bin(int n);
    public int bin2int(String s);
}

public class BinOperations implements BinConverter {

    @Override
    public String int2bin(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("El número no puede ser negativo.");
        }
        return int2binRecursive(n);
    }

    private String int2binRecursive(int n) {
        // Caso base: si el número es 0 o 1
        if (n == 0) {
            return "0";
        }
        if (n == 1) {
            return "1";
        }

        // Llamada recursiva
        return int2binRecursive(n / 2) + (n % 2);
    }

    @Override
    public int bin2int(String s) {
        if (!s.matches("[01]+")) {
            throw new IllegalArgumentException("La cadena no es una representación binaria válida.");
        }
        return bin2intRecursive(s);
    }

    private int bin2intRecursive(String s) {
        // Caso base: si la cadena es vacía
        if (s.isEmpty()) {
            return 0;
        }

        // Llamada recursiva
        int lastDigit = Character.getNumericValue(s.charAt(s.length() - 1));
        return bin2intRecursive(s.substring(0, s.length() - 1)) * 2 + lastDigit;
    }

    public static void main(String[] args) {
        BinOperations binOps = new BinOperations();

        // Pruebas para int2bin
        try {
            System.out.println("Testing int2bin(-100): throws an IllegalArgumentException, " + (binOps.int2bin(-100).equals("throws an IllegalArgumentException") ? "OK" : "FAIL"));
        } catch (IllegalArgumentException e) {
            System.out.println("Testing int2bin(-100): throws an IllegalArgumentException, OK");
        }

        try {
            System.out.println("Testing int2bin(-1): throws an IllegalArgumentException, " + (binOps.int2bin(-1).equals("throws an IllegalArgumentException") ? "OK" : "FAIL"));
        } catch (IllegalArgumentException e) {
            System.out.println("Testing int2bin(-1): throws an IllegalArgumentException, OK");
        }

        System.out.println("Testing int2bin(0): " + (binOps.int2bin(0).equals("0") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(1): " + (binOps.int2bin(1).equals("1") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(2): " + (binOps.int2bin(2).equals("10") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(3): " + (binOps.int2bin(3).equals("11") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(4): " + (binOps.int2bin(4).equals("100") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(5): " + (binOps.int2bin(5).equals("101") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(6): " + (binOps.int2bin(6).equals("110") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(7): " + (binOps.int2bin(7).equals("111") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(8): " + (binOps.int2bin(8).equals("1000") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(9): " + (binOps.int2bin(9).equals("1001") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(10): " + (binOps.int2bin(10).equals("1010") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(25): " + (binOps.int2bin(25).equals("11001") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(256): " + (binOps.int2bin(256).equals("100000000") ? "OK" : "FAIL"));
        System.out.println("Testing int2bin(2344): " + (binOps.int2bin(2344).equals("100100101000") ? "OK" : "FAIL"));

        // Pruebas para bin2int
        try {
            System.out.println("Testing bin2int(\"00121011\"): throws an IllegalArgumentException, " + (binOps.bin2int("00121011") == 0 ? "OK" : "FAIL"));
        } catch (IllegalArgumentException e) {
            System.out.println("Testing bin2int(\"00121011\"): throws an IllegalArgumentException, OK");
        }

        try {
            System.out.println("Testing bin2int(\"00110alcortes\"): throws an IllegalArgumentException, " + (binOps.bin2int("00110alcortes") == 0 ? "OK" : "FAIL"));
        } catch (IllegalArgumentException e) {
            System.out.println("Testing bin2int(\"00110alcortes\"): throws an IllegalArgumentException, OK");
        }

        try {
            System.out.println("Testing bin2int(\"hello\"): throws an IllegalArgumentException, " + (binOps.bin2int("hello") == 0 ? "OK" : "FAIL"));
        } catch (IllegalArgumentException e) {
            System.out.println("Testing bin2int(\"hello\"): throws an IllegalArgumentException, OK");
        }

        System.out.println("Testing bin2int(\"0\"): " + (binOps.bin2int("0") == 0 ? "OK" : "FAIL"));
        System.out.println("Testing bin2int(\"1\"): " + (binOps.bin2int("1") == 1 ? "OK" : "FAIL"));
        System.out.println("Testing bin2int(\"10\"): " + (binOps.bin2int("10") == 2 ? "OK" : "FAIL"));
