public class CandleCounterRecursive implements CandleCounter {

    @Override
    public String getImplementationDescription() {
        return "Recursive";
    }

    @Override
    public long count(long years) {
        // Caso base: si los años son 0, no hay velas
        if (years == 0) {
            return 0;
        }
        // Caso recursivo: sumar el número de velas del año actual a la suma de los años anteriores
        return years + count(years - 1);
    }

