        for (int i = 0; i < puntos.length; i++) {
            puntos[i] = new Punto(i * 1.0, i * 2.0);
        }

        // Imprimir los elementos del array de puntos después de la inicialización con el bucle for
        for (int i = 0; i < puntos.length; i++) {
            System.out.println("Punto en la posición " + i + ": " + puntos[i]);
        }

        // Otra forma: Inicialización por asignación directa
        Punto[] otrosPuntos = {
