public class Ticket {
    // Atributos privados
    private int seat;
    private double basePrice;

    // Constructor que inicializa los atributos y lanza la excepción si la fila es inferior a 6
    public Ticket(int seat, double basePrice) throws IncorrectSeatException {
        if (seat < 6) {
            throw new IncorrectSeatException("El asiento no puede estar en una fila inferior a 6 para un billete de tipo Basic.");
        }
        this.seat = seat;
        this.basePrice = basePrice;
    }

    // Métodos get para acceder a los atributos
