        return seat;
    }

    public double getBasePrice() {
        return basePrice;
    }

    // Método para calcular el precio final del billete
    public double calculateFinalPrice() {
        // En esta clase no se tiene la información suficiente para realizar el cálculo
        // Este método debería ser implementado en una subclase que tenga la información necesaria
        return basePrice; // Retorno basePrice como placeholder
    }

    // Sobrescribe el método toString() de la clase Object
    @Override
    public String toString() {
        return "Ticket{" +
                "seat=" + seat +
                ", basePrice=" + basePrice +
                '}';
    }
}
