```java
public class StoreManager {
    private BinaryTree<Customer> storeCustomers;
    private LinkedQueue<Order> ordersToProcess;

    public StoreManager() {
        storeCustomers = new BinaryTree<>();
        ordersToProcess = new LinkedQueue<>();
    }

    public void addCustomer(Customer customer) {
        storeCustomers.insert(customer);
    }

    public void addOrder(Order order) {
        ordersToProcess.enqueue(order);
    }

    public double totalValueAccount(String customerId) {
        double total = 0.0;
        LinkedQueue<Order> tempQueue = new LinkedQueue<>();

        while (!ordersToProcess.isEmpty()) {
            Order order = ordersToProcess.dequeue();
            if (order.getClientId().equals(customerId)) {
                total += order.getTotalPrice();
            }
            tempQueue.enqueue(order);
        }

        while (!tempQueue.isEmpty()) {
            ordersToProcess.enqueue(tempQueue.dequeue());
        }

        return total;
    }

    public void updateAccount(Customer key) {
        BSTree<Customer> result = storeCustomers.search(key);
        if (result != null) {
            Customer customer = result.getInfo();
            double value = totalValueAccount(customer.getId());
            customer.setAccount(customer.getAccount() + value);
        }
    }

    public void displayCustomers() {
        storeCustomers.inorderTraversal();
    }
}
```

