```java
// Implementación simplificada de LinkedQueue
public class LinkedQueue<E> implements Queue<E> {
    private Node<E> front;
    private Node<E> rear;
    private int size;

    public LinkedQueue() {
        front = null;
        rear = null;
        size = 0;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    public void enqueue(E info) {
        Node<E> newNode = new Node<>(info);
        if (rear != null) {
            rear.setNext(newNode);
        }
        rear = newNode;
        if (front == null) {
            front = newNode;
        }
        size++;
    }

    public E dequeue() {
        if (isEmpty()) {
            return null;
        }
        E info = front.getInfo();
        front = front.getNext();
        if (front == null) {
            rear = null;
        }
        size--;
        return info;
    }

    public E front() {
        if (isEmpty()) {
            return null;
        }
        return front.getInfo();
    }

    // Otros métodos relevantes
}

