    public static void main(String[] args) {
        BinaryTree<Integer> binaryTree = new BinaryTree<>();

        binaryTree.insert(10);
        binaryTree.insert(5);
        binaryTree.insert(15);

        System.out.println("Inorder traversal of the tree:");
        binaryTree.inorderTraversal();

        if (binaryTree.hasLeftChild()) {
            System.out.println("\nThe root has a left child.");
        } else {
            System.out.println("\nThe root does not have a left child.");
        }

        if (binaryTree.hasRightChild()) {
            System.out.println("The root has a right child.");
        } else {
            System.out.println("The root does not have a right child.");
        }
    }
}
```

