public class StoreManager {
    private LBSTree<Customer> storeCustomers;
    private LinkedQueue<Order> ordersToProcess;

    public StoreManager() {
        storeCustomers = new LBSTree<>();
        ordersToProcess = new LinkedQueue<>();
    }

    // Métodos para gestionar clientes
    public void addCustomer(Customer customer) {
        storeCustomers.insert(customer);
    }

    public Customer findCustomer(int id) {
        return storeCustomers.find(new Customer("", id)); // Asumiendo que la búsqueda se hace por ID
    }

    // Métodos para gestionar pedidos
    public void addOrder(Order order) {
        ordersToProcess.enqueue(order);
    }

    public Order processNextOrder() {
        if (!ordersToProcess.isEmpty()) {
            return ordersToProcess.dequeue();
        }
        return null; // No hay pedidos para procesar
    }

    public boolean hasPendingOrders() {
        return !ordersToProcess.isEmpty();
    }

    public int pendingOrdersCount() {
        return ordersToProcess.size();
    }

    // Otros métodos relevantes
}
