// Implementación simplificada de LBSTree
public class LBSTree<E extends Comparable<E>> {
    private LBNode<E> root;

    public LBSTree() {
        root = null;
    }

    public void insert(E info) {
        root = insertRec(root, info);
    }

    private LBNode<E> insertRec(LBNode<E> node, E info) {
        if (node == null) {
            node = new LBNode<>(info);
            return node;
        }
        if (info.compareTo(node.getInfo()) < 0) {
            node.setLeft(insertRec(node.getLeft(), info));
        } else if (info.compareTo(node.getInfo()) > 0) {
            node.setRight(insertRec(node.getRight(), info));
        }
        return node;
    }

    public BSTree<E> search(Comparable c) {
        return searchRec(root, c);
    }

    private BSTree<E> searchRec(LBNode<E> node, Comparable c) {
        if (node == null || node.getInfo().equals(c)) {
            return node != null ? new BSTree<>(node) : null;
        }
        if (c.compareTo(node.getInfo()) < 0) {
            return searchRec(node.getLeft(), c);
        } else {
            return searchRec(node.getRight(), c);
        }
    }

    // Otros métodos relevantes
}

// Implementación simplificada de LinkedQueue
public class LinkedQueue<E> implements Queue<E> {
    private Node<E> front;
    private Node<E> rear;
    private int size;

    public LinkedQueue() {
        front = null;
        rear = null;
        size = 0;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    public void enqueue(E info) {
        Node<E> newNode = new Node<>(info);
        if (rear != null) {
            rear.setNext(newNode);
        }
        rear = newNode;
        if (front == null) {
            front = newNode;
        }
        size++;
    }

    public E dequeue() {
        if (isEmpty()) {
            return null;
        }
        E info = front.getInfo();
        front = front.getNext();
        if (front == null) {
            rear = null;
        }
        size--;
        return info;
    }

    public E front() {
        if (isEmpty()) {
            return null;
        }
        return front.getInfo();
    }

    // Otros métodos relevantes
}

