### Clase `Figure`

Primero, definimos la clase abstracta `Figure`:

```java
package Session6;

public abstract class Figure {
    private String name;

    public Figure(String name) {
        this.name = name;
    }

    abstract public double area();
    abstract public boolean isRegular();

    protected String getName() {
        return name;
    }

    protected void setName(String name) {
        this.name = name;
    }
}
```

### Clase `Circle`

Luego, definimos la clase `Circle` que hereda de `Figure`:

```java
package Session6;

public class Circle extends Figure {
    private Point center;
    private int radius;

    public Circle(String name, Point center, int radius) {
        super(name);
        this.center = center;
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }

    @Override
    public boolean isRegular() {
        return true; // Los círculos siempre son regulares
    }

    @Override
    public String toString() {
        return "Circle[name=" + getName() + ", center=" + center + ", radius=" + radius + "]";
    }

    public Point getCenter() {
        return center;
    }

    public void setCenter(Point center) {
        this.center = center;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }
}
```

### Clase `Triangle`

Definimos la clase `Triangle` que hereda de `Figure`:

```java
package Session6;

public class Triangle extends Figure {
    private Point v1, v2, v3;

    public Triangle(String name, Point v1, Point v2, Point v3) {
        super(name);
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    @Override
    public double area() {
        double Ax = v1.getX(), Ay = v1.getY();
        double Bx = v2.getX(), By = v2.getY();
        double Cx = v3.getX(), Cy = v3.getY();
        return 0.5 * Math.abs(Ax * (By - Cy) + Bx * (Cy - Ay) + Cx * (Ay - By));
    }

    @Override
    public boolean isRegular() {
        double side1 = v1.distance(v2);
        double side2 = v2.distance(v3);
        double side3 = v3.distance(v1);
        return side1 == side2 && side2 == side3;
    }

    @Override
    public String toString() {
        return "Triangle[name=" + getName() + ", v1=" + v1 + ", v2=" + v2 + ", v3=" + v3 + "]";
    }

    public Point getV1() {
        return v1;
    }

    public void setV1(Point v1) {
        this.v1 = v1;
    }

    public Point getV2() {
        return v2;
    }

    public void setV2(Point v2) {
        this.v2 = v2;
    }

    public Point getV3() {
        return v3;
    }

    public void setV3(Point v3) {
        this.v3 = v3;
    }
}
```

### Clase `Quadrilateral`

Definimos la clase abstracta `Quadrilateral` que hereda de `Figure`:

```java
package Session6;

public abstract class Quadrilateral extends Figure {
    private Point v1, v2, v3, v4;

    public Quadrilateral(String name, Point v1, Point v2, Point v3, Point v4) {
        super(name);
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
        this.v4 = v4;
    }

    @Override
    public boolean isRegular() {
        return checkRectangle(v1, v2, v3, v4);
    }

    @Override
    public String toString() {
        return "Quadrilateral[name=" + getName() + ", v1=" + v1 + ", v2=" + v2 + ", v3=" + v3 + ", v4=" + v4 + "]";
    }

    public Point getV1() {
        return v1;
    }

    public void setV1(Point v1) {
        this.v1 = v1;
    }

    public Point getV2() {
        return v2;
    }

    public void setV2(Point v2) {
        this.v2 = v2;
    }

    public Point getV3() {
        return v3;
    }

    public void setV3(Point v3) {
        this.v3 = v3;
    }

    public Point getV4() {
        return v4;
    }

    public void setV4(Point v4) {
        this.v4 = v4;
    }

    private boolean checkRectangle(Point v1, Point v2, Point v3, Point v4) {
        Point auxVertex = v1.nearest(new Point[]{v2, v3, v4});
        if (auxVertex.equals(v2)) {
            return v1.distance(v3) == v2.distance(v4)
                && v1.distance(v4) == v2.distance(v3)
                && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v3, v4}));
        } else if (auxVertex.equals(v3)) {
            return v1.distance(v2) == v3.distance(v4)
                && v1.distance(v4) == v3.distance(v2)
                && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v2, v4}));
        } else if (auxVertex.equals(v4)) {
            return v1.distance(v2) == v4.distance(v3)
                && v1.distance(v3) == v4.distance(v2)
                && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v2, v3}));
        } else {
            return false;
        }
    }

    private boolean scalarProduct(Point p1, Point p2, Point p3) {
        return (p3.getY() - p1.getY()) * (p2.getY() - p1.getY())
            + (p3.getX() - p1.getX()) * (p2.getX() - p1.getX()) == 0;
    }
}
```

### Clase `Rectangle`

Definimos la clase `Rectangle` que hereda de `Quadrilateral`:

```java
package Session6;

public class Rectangle extends Quadrilateral {
    public Rectangle(String name, Point v1, Point v2, Point v3, Point v4) throws Exception {
        super(name, v1, v2, v3, v4);
        if (!isRegular()) {
            throw new Exception("The provided points do not form a rectangle.");
        }
    }

    @Override
    public double area() {
        Point nearest1 = getV1().nearest(new Point[]{getV2(), getV3(), getV4()});
        Point nearest2 = getV1().nearest(new Point[]{getV2(), getV3(), getV4()});
        return getV1().distance(nearest1) * getV1().distance(nearest2);
    }

    @Override
    public String toString() {
        return super.toString();
    }
}
```

### Clase `FiguresSet`

Definimos la clase `FiguresSet` que contiene varias figuras y calcula el área total:

```java
package Session6;

import java.util.ArrayList;

public class FiguresSet {
    private ArrayList<Figure> figures;

    public FiguresSet() {
        figures = new ArrayList<>();
    }

    public void addFigure(Figure f) {
        figures.add(f);
    }

    public double totalArea() {
        double total = 0;
        for (Figure f : figures) {
            total += f.area();
        }
        return total;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Figure f : figures) {
            sb.append(f.toString()).append("\n");
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        FiguresSet set = new FiguresSet();

        Circle circle = new Circle("Circle1", new Point(0, 0), 5);
        Triangle triangle = new Triangle("Triangle1", new Point(0, 0), new Point(3, 0), new Point(0, 4));
        Rectangle rectangle = new Rectangle("Rectangle1", new Point(0, 0), new Point(4, 0), new Point(4, 3), new Point(0, 3));

        set.addFigure(circle);
        set.addFigure(triangle);
        set.addFigure(rectangle);

        System.out.println("Total area: " + set.totalArea());
        System.out.println("Figures:\n" + set);
    }
}
```

### Clase `Point`

Asegúrate de que la clase `Point` esté correctamente definida:

```java
package Session6;

public class Point {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public double distance(Point other) {
        double dx = this.x - other.x;
        double dy = this.y - other.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    public Point nearest(Point[] otherPoints) {
        Point nearestPoint = null;
        double minDistance = Double.MAX_VALUE;
        for (Point p : otherPoints) {
            double currentDistance = this.distance(p);
            if (currentDistance < minDistance) {
                minDistance = currentDistance;
                nearestPoint = p;
            }
        }
        return nearestPoint;
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}
```

