        return v2;
    }

    public void setV2(Point v2) {
        this.v2 = v2;
    }

    public Point getV3() {
        return v3;
    }

    public void setV3(Point v3) {
        this.v3 = v3;
    }
}
```

- **Constructor**: The constructor of the `Triangle` class calls the constructor of the `Figure` class using `super(name)` to initialize the `name` attribute.
