        this.v4 = v4;
    }

    @Override
    public boolean isRegular() {
        return checkRectangle(v1, v2, v3, v4);
    }

    @Override
    public String toString() {
        return "Quadrilateral[name=" + getName() + ", v1=" + v1 + ", v2=" + v2 + ", v3=" + v3 + ", v4=" + v4 + "]";
    }

    public Point getV1() {
        return v1;
    }

    public void setV1(Point v1) {
        this.v1 = v1;
    }

    public Point getV2() {
        return v2;
    }

    public void setV2(Point v2) {
        this.v2 = v2;
    }

    public Point getV3() {
        return v3;
    }

    public void setV3(Point v3) {
        this.v3 = v3;
    }

    public Point getV4() {
        return v4;
    }

    public void setV4(Point v4) {
        this.v4 = v4;
    }

    private boolean checkRectangle(Point v1, Point v2, Point v3, Point v4) {
        Point auxVertex = v1.nearest(new Point[]{v2, v3, v4});
        if (auxVertex.equals(v2)) {
            return v1.distance(v3) == v2.distance(v4)
                && v1.distance(v4) == v2.distance(v3)
                && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v3, v4}));
        } else if (auxVertex.equals(v3)) {
            return v1.distance(v2) == v3.distance(v4)
                && v1.distance(v4) == v3.distance(v2)
                && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v2, v4}));
        } else if (auxVertex.equals(v4)) {
            return v1.distance(v2) == v4.distance(v3)
                && v1.distance(v3) == v4.distance(v2)
                && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v2, v3}));
        } else {
            return false;
        }
    }

    private boolean scalarProduct(Point p1, Point p2, Point p3) {
        return (p3.getY() - p1.getY()) * (p2.getY() - p1.getY())
            + (p3.getX() - p1.getX()) * (p2.getX() - p1.getX()) == 0;
    }
}
```

### Explicación del Uso de `v1`, `v2`, `v3`, `v4` y `p1`, `p2`, `p3`

1. **Atributos `v1`, `v2`, `v3`, `v4`**:
    - Estos atributos representan los cuatro vértices del cuadrilátero y son utilizados en los métodos de la clase `Quadrilateral`.

2. **Método `checkRectangle`**:
    - Este método utiliza los atributos `v1`, `v2`, `v3`, `v4` para verificar si los puntos forman un rectángulo.
    - Dentro del método, se utiliza `v1` para encontrar el vértice más cercano (`auxVertex`) entre `v2`, `v3` y `v4`.
    - Dependiendo de cuál vértice es el más cercano (`auxVertex`), se realizan comparaciones de distancias y se calcula el producto escalar para verificar ángulos rectos.

3. **Método `scalarProduct`**:
    - Este método calcula el producto escalar para verificar si los puntos forman ángulos rectos.
    - Los parámetros `p1`, `p2`, `p3` son puntos específicos utilizados en el cálculo del producto escalar.

### Ejemplo de Uso

Aquí tienes un ejemplo de cómo crear un cuadrilátero y verificar si es regular:

```java
package Session6;

public class Main {
    public static void main(String[] args) throws Exception {
        Point p1 = new Point(0, 0);
        Point p2 = new Point(4, 0);
        Point p3 = new Point(4, 3);
        Point p4 = new Point(0, 3);

        Quadrilateral quad = new Rectangle("Rectangle1", p1, p2, p3, p4);

        System.out.println(quad);
        System.out.println("Is regular: " + quad.isRegular());
    }
}
```

### Output

El output será:

```
Quadrilateral[name=Rectangle1, v1=(0.0, 0.0), v2=(4.0, 0.0), v3=(4.0, 3.0), v4=(0.0, 3.0)]
Is regular: true
```

### Resumen

- **Atributos `v1`, `v2`, `v3`, `v4`**: Representan los cuatro vértices del cuadrilátero.
- **Método `checkRectangle`**: Utiliza los atributos `v1`, `v2`, `v3`, `v4` para verificar si los puntos forman un rectángulo.
- **Método `scalarProduct`**: Calcula el producto escalar para verificar ángulos rectos utilizando puntos específicos (`p1`, `p2`, `p3`).

