public class Triangle {
    private Point vertex1;
    private Point vertex2;
    private Point vertex3;

    public Triangle(Point vertex1, Point vertex2, Point vertex3) {
        this.vertex1 = vertex1;
        this.vertex2 = vertex2;
        this.vertex3 = vertex3;
    }

    public Point getVertex1() {
        return vertex1;
    }

    public Point getVertex2() {
        return vertex2;
    }

    public Point getVertex3() {
        return vertex3;
    }

    public static void main(String[] args) {
        Point p1 = new Point(0, 0);
        Point p2 = new Point(1, 0);
        Point p3 = new Point(0, 1);

        Triangle triangle = new Triangle(p1, p2, p3);

        System.out.println("Vértice 1: (" + triangle.getVertex1().getX() + ", " + triangle.getVertex1().getY() + ")");
        System.out.println("Vértice 2: (" + triangle.getVertex2().getX() + ", " + triangle.getVertex2().getY() + ")");
        System.out.println("Vértice 3: (" + triangle.getVertex3().getX() + ", " + triangle.getVertex3().getY() + ")");
    }
}
```

En este ejemplo:

