public class LBNode<E> implements BTree<E> {
    private E info;
    private BTree<E> left;
    private BTree<E> right;

    public LBNode(E info, BTree<E> left, BTree<E> right) {
        this.info = info;
        this.left = left;
        this.right = right;
    }

    @Override
    public boolean isEmpty() {
        return info == null && left == null && right == null;
    }

    @Override
    public E getInfo() {
        return info;
    }

    public void setInfo(E info) {
        this.info = info;
    }

    @Override
    public BTree<E> getLeft() {
        return left;
    }

    public void setLeft(BTree<E> left) {
        this.left = left;
    }

    @Override
    public BTree<E> getRight() {
        return right;
    }

    public void setRight(BTree<E> right) {
        this.right = right;
    }

    @Override
    public void insert(BTree<E> tree, int side) {
        if (side == LEFT) {
            left = tree;
        } else if (side == RIGHT) {
            right = tree;
        }
    }

    @Override
    public BTree<E> extract(int side) {
        BTree<E> extractedTree = null;
        if (side == LEFT) {
            extractedTree = left;
            left = null;
        } else if (side == RIGHT) {
            extractedTree = right;
            right = null;
        }
        return extractedTree;
    }

    @Override
    public String toStringPreOrder() {
        StringBuilder sb = new StringBuilder();
        sb.append(info).append(" ");
        if (left != null) {
            sb.append(left.toStringPreOrder());
        }
        if (right != null) {
            sb.append(right.toStringPreOrder());
        }
        return sb.toString();
    }

    @Override
    public String toStringInOrder() {
        StringBuilder sb = new StringBuilder();
        if (left != null) {
            sb.append(left.toStringInOrder());
        }
        sb.append(info).append(" ");
        if (right != null) {
            sb.append(right.toStringInOrder());
        }
        return sb.toString();
    }

    @Override
    public String toStringPostOrder() {
        StringBuilder sb = new StringBuilder();
        if (left != null) {
            sb.append(left.toStringPostOrder());
        }
        if (right != null) {
            sb.append(right.toStringPostOrder());
        }
        sb.append(info).append(" ");
        return sb.toString();
    }

    @Override
    public String toString() {
        return toStringPreOrder();
    }

    @Override
    public int size() {
        int size = 1; // Count the current node
        if (left != null) {
            size += left.size();
        }
        if (right != null) {
            size += right.size();
        }
        return size;
    }

    @Override
    public int height() {
        int leftHeight = (left != null) ? left.height() : 0;
        int rightHeight = (right != null) ? right.height() : 0;
        return 1 + Math.max(leftHeight, rightHeight);
    }

    @Override
    public boolean equals(BTree<E> tree) {
        if (tree == null) {
            return false;
        }
        if (!info.equals(tree.getInfo())) {
            return false;
        }
        boolean leftEquals = (left == null) ? tree.getLeft() == null : left.equals(tree.getLeft());
        boolean rightEquals = (right == null) ? tree.getRight() == null : right.equals(tree.getRight());
        return leftEquals && rightEquals;
    }

    @Override
    public boolean find(BTree<E> tree) {
        if (tree == null) {
            return false;
        }
        if (this.equals(tree)) {
            return true;
        }
        boolean foundInLeft = (left != null) ? left.find(tree) : false;
        boolean foundInRight = (right != null) ? right.find(tree) : false;
        return foundInLeft || foundInRight;
    }
}
