### **Ejercicio 1: Árbol Binario de Búsqueda**

**Enunciado**: Implementa un árbol binario de búsqueda (BST) en Java. Debes incluir métodos para insertar un nodo, buscar un nodo y recorrer el árbol en orden.

### **Solución**

```java
class Node {
    int value;
    Node left, right;

    public Node(int item) {
        value = item;
        left = right = null;
    }
}

class BinarySearchTree {
    Node root;

    BinarySearchTree() {
        root = null;
    }

    void insert(int value) {
        root = insertRec(root, value);
    }

    Node insertRec(Node root, int value) {
        if (root == null) {
            root = new Node(value);
            return root;
        }
        if (value < root.value)
            root.left = insertRec(root.left, value);
        else if (value > root.value)
            root.right = insertRec(root.right, value);
        return root;
    }

    boolean search(int value) {
        return searchRec(root, value);
    }

    boolean searchRec(Node root, int value) {
        if (root == null)
            return false;
        if (root.value == value)
            return true;
        return value < root.value ? searchRec(root.left, value) : searchRec(root.right, value);
    }

    void inorder() {
        inorderRec(root);
    }

    void inorderRec(Node root) {
        if (root != null) {
            inorderRec(root.left);
            System.out.print(root.value + " ");
            inorderRec(root.right);
        }
    }

    public static void main(String[] args) {
        BinarySearchTree tree = new BinarySearchTree();
        tree.insert(50);
        tree.insert(30);
        tree.insert(20);
        tree.insert(40);
        tree.insert(70);
        tree.insert(60);
        tree.insert(80);

        System.out.println("Recorrido en orden:");
        tree.inorder();

        System.out.println("\nBuscar 40: " + tree.search(40));
        System.out.println("Buscar 90: " + tree.search(90));
    }
}
```

### **Ejercicio 2: Lista Enlazada**

**Enunciado**: Implementa una lista enlazada simple en Java. Debes incluir métodos para agregar un nodo al final, eliminar un nodo y mostrar la lista.

### **Solución**

```java
class Node {
    int data;
    Node next;

    Node(int d) {
        data = d;
        next = null;
    }
}

class LinkedList {
    Node head;

    public void append(int new_data) {
        Node new_node = new Node(new_data);
        if (head == null) {
            head = new_node;
            return;
        }
        Node last = head;
        while (last.next != null)
            last = last.next;
        last.next = new_node;
    }

    void deleteNode(int key) {
        Node temp = head, prev = null;
        if (temp != null && temp.data == key) {
            head = temp.next;
            return;
        }
        while (temp != null && temp.data != key) {
            prev = temp;
            temp = temp.next;
        }
        if (temp == null) return;
        prev.next = temp.next;
    }

    public void printList() {
        Node tnode = head;
        while (tnode != null) {
            System.out.print(tnode.data + " ");
            tnode = tnode.next;
        }
    }

    public static void main(String[] args) {
        LinkedList llist = new LinkedList();
        llist.append(1);
        llist.append(2);
        llist.append(3);
        llist.append(4);

        System.out.println("Lista enlazada:");
        llist.printList();

        llist.deleteNode(3);
        System.out.println("\nLista después de eliminar el nodo con valor 3:");
        llist.printList();
    }
}
```

### **Ejercicio 3: Pila**

**Enunciado**: Implementa una pila en Java utilizando un array. Debes incluir métodos para apilar (push), desapilar (pop) y mostrar el contenido de la pila.

### **Solución**

```java
class Stack {
    static final int MAX = 1000;
    int top;
    int[] stack = new int[MAX];

    Stack() {
        top = -1;
    }

    boolean isEmpty() {
        return (top < 0);
    }

    boolean push(int x) {
        if (top >= (MAX - 1)) {
            System.out.println("Stack Overflow");
            return false;
        } else {
            stack[++top] = x;
            return true;
        }
    }

    int pop() {
        if (top < 0) {
            System.out.println("Stack Underflow");
            return -1;
        } else {
            int x = stack[top--];
            return x;
        }
    }

    void printStack() {
        for (int i = top; i >= 0; i--) {
            System.out.print(stack[i] + " ");
        }
    }

    public static void main(String[] args) {
        Stack s = new Stack();
        s.push(10);
        s.push(20);
        s.push(30);

        System.out.println("Contenido de la pila:");
        s.printStack();

        System.out.println("\nElemento desapilado: " + s.pop());
        System.out.println("Contenido de la pila después de desapilar:");
        s.printStack();
    }
}
```

### **Ejercicio 4: Cola**

**Enunciado**: Implementa una cola en Java utilizando un array. Debes incluir métodos para encolar (enqueue), desencolar (dequeue) y mostrar el contenido de la cola.

### **Solución**

```java
class Queue {
    static final int MAX = 1000;
    int front, rear, size;
    int[] queue = new int[MAX];

    Queue() {
        front = this.size = 0;
        rear = MAX - 1;
    }

    boolean isFull() {
        return (size == MAX);
    }

    boolean isEmpty() {
        return (size == 0);
    }

    boolean enqueue(int item) {
        if (isFull()) {
            System.out.println("Queue Overflow");
            return false;
        }
        rear = (rear + 1) % MAX;
        queue[rear] = item;
        size++;
        return true;
    }

    int dequeue() {
        if (isEmpty()) {
            System.out.println("Queue Underflow");
            return -1;
        }
        int item = queue[front];
        front = (front + 1) % MAX;
        size--;
        return item;
    }

    void printQueue() {
        for (int i = front; i <= rear; i++) {
            System.out.print(queue[i] + " ");
        }
    }

    public static void main(String[] args) {
        Queue q = new Queue();
        q.enqueue(10);
        q.enqueue(20);
        q.enqueue(30);

        System.out.println("Contenido de la cola:");
        q.printQueue();

        System.out.println("\nElemento desencolado: " + q.dequeue());
        System.out.println("Contenido de la cola después de desencolar:");
        q.printQueue();
    }
}
```

