            };

            Point nearestPoint = point.nearest(points);
            System.out.println("Nearest point: " + nearestPoint.toString());
        } catch (NumberFormatException e) {
            System.out.println("Numbers must be real numbers.");
        }
    }
}
```

### Explicación del código de prueba

