        this.info = info;
        this.next = next;
    }

    public Node<E> getNext() {
        return next;
    }

    public void setNext(Node<E> next) {
        this.next = next;
    }

    public E getInfo() {
        return info;
    }

    public void setInfo(E info) {
        this.info = info;
    }
}
```

#### Clase `LinkedList`
```java
public class LinkedList<E> {
    private Node<E> first;

    public LinkedList() {
        first = null;
    }

    // Método para agregar un nodo al principio de la lista
    public void addFirst(E info) {
        first = new Node<>(info, first);
    }

    // Método para eliminar el primer nodo de la lista
    public E removeFirst() {
        if (first != null) {
            E info = first.getInfo();
            first = first.getNext(); // Actualizar la referencia del primer nodo
            return info;
        } else {
            return null; // La lista está vacía
        }
    }

    // Método para imprimir la lista
    public void printList() {
