Vamos a implementar la clase `MyBasicLinkedList<E>` siguiendo las pautas proporcionadas. Esta clase utilizará la clase `Node<E>` que hemos implementado anteriormente.

### Implementación de la clase `MyBasicLinkedList<E>`

```java
public class MyBasicLinkedList<E> {
    private Node<E> first;
    private int size;

    // Constructor
    public MyBasicLinkedList() {
        this.first = null;
        this.size = 0;
    }

    // Método para verificar si la lista está vacía
    public boolean isEmpty() {
        return first == null;
    }

    // Método para insertar un nodo al principio de la lista
    public void insert(E info) {
        Node<E> newNode = new Node<>(info);
        newNode.setNext(first);
        first = newNode;
        size++;
    }

    // Método para extraer el primer nodo de la lista
    public E extract() {
        if (isEmpty()) {
            return null;
        }
        Node<E> temp = first;
        first = first.getNext();
        size--;
        return temp.getInfo();
    }

    // Método para insertar un nodo después de un nodo previo
    public void insert(E info, Node<E> previous) {
        if (previous == null) {
            insert(info);
        } else {
            Node<E> newNode = new Node<>(info);
            newNode.setNext(previous.getNext());
            previous.setNext(newNode);
            size++;
        }
    }

    // Método para extraer el nodo siguiente a un nodo previo
    public E extract(Node<E> previous) {
        if (previous == null || previous.getNext() == null) {
            return null;
        }
        Node<E> temp = previous.getNext();
        previous.setNext(temp.getNext());
        size--;
        return temp.getInfo();
    }

    // Método para obtener el tamaño de la lista
    public int size() {
        return size;
    }

    // Método para obtener la representación textual de la lista
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        Node<E> current = first;
        while (current != null) {
            sb.append(current.getInfo());
            if (current.getNext() != null) {
                sb.append(" -> ");
            }
            current = current.getNext();
        }
        return sb.toString();
    }

    // Método para imprimir la lista
    public void print() {
        System.out.println(this.toString());
    }

    // Método para buscar un nodo por su información
    public Node<E> searchNode(E info) {
        Node<E> current = first;
        while (current != null) {
            if (current.getInfo().equals(info)) {
                return current;
            }
            current = current.getNext();
        }
        return null;
    }

    // Método para buscar un nodo por su posición
    public Node<E> searchNode(int n) {
        if (n < 0 || n >= size) {
            return null;
        }
        Node<E> current = first;
        for (int i = 0; i < n; i++) {
            current = current.getNext();
        }
        return current;
    }

    // Método para buscar el último nodo de la lista
    public Node<E> searchLastNode() {
        if (isEmpty()) {
            return null;
        }
        Node<E> current = first;
        while (current.getNext() != null) {
            current = current.getNext();
        }
        return current;
    }

    // Método para buscar la posición de un elemento en la lista
    public int search(E info) {
        Node<E> current = first;
        int position = 0;
        while (current != null) {
            if (current.getInfo().equals(info)) {
                return position;
            }
            current = current.getNext();
            position++;
        }
        return -1;
    }
}
```

