        Node<E> n = new Node<E>(info, null);
        if (isEmpty()) {
            top = n;
        } else {
            tail.setNext(n);
        }
        tail = n;
        size++;
    }

    @Override
    public E dequeue() {
        E info;
        if (isEmpty()) {
            info = null;
        } else {
            info = top.getInfo();
            top = top.getNext();
            size--;
            if (isEmpty()) {
