### LinkedQueue.java
```java
package EjClase;

public class LinkedQueue<E> implements Queue<E> {
    private Node<E> top;
    private Node<E> tail;
    private int size;

    public LinkedQueue() {
        top = null;
        tail = null;
        size = 0;
    }

    @Override
    public boolean isEmpty() {
        return (top == null);
    }

    @Override
    public int size() {
        return size;
    }

    @Override
    public void enqueue(E info) {
        Node<E> n = new Node<E>(info, null);
        if (isEmpty()) {
            top = n;
        } else {
            tail.setNext(n);
        }
        tail = n;
        size++;
    }

    @Override
    public E dequeue() {
        if (isEmpty()) {
            return null;
        } else {
            E info = top.getInfo();
            top = top.getNext();
            size--;
            if (isEmpty()) {
                tail = null;
            }
            return info;
        }
    }

    @Override
    public E front() {
        if (isEmpty()) {
            return null;
        } else {
            return top.getInfo();
        }
    }
}
```

