```java
public class Triangulo extends Figura {
    private double Ax, Ay, Bx, By, Cx, Cy;

    public Triangulo(double Ax, double Ay, double Bx, double By, double Cx, double Cy) {
        super(0, 0); // No necesitamos dim1 y dim2 para el triángulo, pero llamamos al constructor de la superclase
        this.Ax = Ax;
