    private boolean isRectangle(Point[] vertexes) {
        if (vertexes.length != 4) {
            return false;
        }
        double d1 = vertexes[0].distanceTo(vertexes[1]);
        double d2 = vertexes[1].distanceTo(vertexes[2]);
        double d3 = vertexes[2].distanceTo(vertexes[3]);
        double d4 = vertexes[3].distanceTo(vertexes[0]);
        double d5 = vertexes[0].distanceTo(vertexes[2]);
        double d6 = vertexes[1].distanceTo(vertexes[3]);

        return d1 == d3 && d2 == d4 && d5 == d6;
    }

