import java.math.BigDecimal;

/**
 * Class that implements the AdvancedPiProvider interface and stores a precalculated value of pi.
 */
public class PiStored implements AdvancedPiProvider {
    private static final String PI = "3.14159265358979323846264338327950"
                                   + "2884197169399375105820974944592307"
                                   + "8164062862089986280348253421170679";
    private int precision;
    private static final int DEFAULT_PRECISION = 30;
    private static final int MAX_PRECISION = PI.length() - 2; // Exclude "3."

    public PiStored() {
        this.precision = DEFAULT_PRECISION;
    }

    @Override
    public void setPrecision(int precision) throws PrecisionException {
        if (precision <= 0 || precision > MAX_PRECISION) {
            throw new PrecisionException("Invalid precision: " + precision);
        }
        this.precision = precision;
    }

    @Override
    public int getPrecision() {
        return precision;
    }

    @Override
    public int getMaximumPrecision() {
        return MAX_PRECISION;
    }

    @Override
    public BigDecimal computePi() {
        String piSubstring = PI.substring(0, precision + 2); // Include "3."
        return new BigDecimal(piSubstring);
    }
}
