```java
// Clase Figure (suponiendo que ya está definida)
public abstract class Figure {
    public abstract double area();
    public abstract boolean isRegular();
    public abstract void set();
    public abstract String toString();
}

// Clase Quadrilateral (suponiendo que ya está definida)
public class Quadrilateral extends Figure {
    protected String name;
    protected Point[] vertexes;

    public Quadrilateral(String name, Point[] vertexes) {
        this.name = name;
        this.vertexes = vertexes;
    }

    @Override
    public double area() {
        // Implementación del cálculo del área para un cuadrilátero genérico
        return 0;
    }

    @Override
    public boolean isRegular() {
        // Implementación para verificar si el cuadrilátero es regular
        return false;
    }

    @Override
    public void set() {
        // Implementación del método set
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Quadrilateral: ").append(name).append("\n");
        for (Point vertex : vertexes) {
            sb.append(vertex.toString()).append("\n");
        }
        return sb.toString();
    }
}

// Clase Point (suponiendo que ya está definida)
public class Point {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double distanceTo(Point other) {
        return Math.sqrt(Math.pow(this.x - other.x, 2) + Math.pow(this.y - other.y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

// Clase Rectangle que hereda de Quadrilateral
public class Rectangle extends Quadrilateral {

    public Rectangle(String name, Point[] vertexes) throws IllegalArgumentException {
        super(name, vertexes);
        if (!isRectangle(vertexes)) {
            throw new IllegalArgumentException("The provided vertexes do not form a rectangle.");
        }
    }

    private boolean isRectangle(Point[] vertexes) {
        if (vertexes.length != 4) {
            return false;
        }
        double d1 = vertexes[0].distanceTo(vertexes[1]);
        double d2 = vertexes[1].distanceTo(vertexes[2]);
        double d3 = vertexes[2].distanceTo(vertexes[3]);
        double d4 = vertexes[3].distanceTo(vertexes[0]);
        double d5 = vertexes[0].distanceTo(vertexes[2]);
        double d6 = vertexes[1].distanceTo(vertexes[3]);

        return d1 == d3 && d2 == d4 && d5 == d6;
    }

    @Override
    public double area() {
        double base = vertexes[0].distanceTo(vertexes[1]);
        double height = vertexes[1].distanceTo(vertexes[2]);
        return base * height;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Rectangle: ").append(name).append("\n");
        for (Point vertex : vertexes) {
            sb.append(vertex.toString()).append("\n");
        }
        return sb.toString();
    }
}
```

