        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    @Override
    public double area() {
        double a = v1.distanceTo(v2);
        double b = v2.distanceTo(v3);
        double c = v3.distanceTo(v1);
        double s = (a + b + c) / 2;
        return Math.sqrt(s * (s - a) * (s - b) * (s - c));
