### Clase `CourtBooking`

```java
import java.util.HashMap;
import java.util.Map;

public class CourtBooking {

    private Map<String, Boolean> courts;

    public CourtBooking() {
        courts = new HashMap<>();
        courts.put("Court1", true);
        courts.put("Court2", true);
        courts.put("Court3", true);
    }

    public boolean isCourtAvailable(String courtName) {
        if (!courts.containsKey(courtName)) {
            throw new IllegalArgumentException("Court does not exist");
        }
        return courts.get(courtName);
    }

    public void bookCourt(String courtName) {
        if (!courts.containsKey(courtName)) {
            throw new IllegalArgumentException("Court does not exist");
        }
        if (!courts.get(courtName)) {
            throw new IllegalStateException("Court is already booked");
        }
        courts.put(courtName, false);
    }

    public void releaseCourt(String courtName) {
