```java
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

public class CourtBookingTest {

    private CourtBooking courtBooking;

    @BeforeEach
    public void setUp() {
        courtBooking = new CourtBooking();
    }

    @AfterEach
    public void tearDown() {
        // Este método se ejecutará después de cada prueba
        System.out.println("Test finalizado. Limpiando recursos si es necesario.");
    }

    @Test
    public void testIsCourtAvailable() {
