        assertFalse(courtBooking.isCourtAvailable("Court1"));
        assertThrows(IllegalStateException.class, () -> courtBooking.bookCourt("Court1"));
        assertThrows(IllegalArgumentException.class, () -> courtBooking.bookCourt("Court4"));
    }

    @Test
    public void testReleaseCourt() {
        courtBooking.bookCourt("Court1");
        courtBooking.releaseCourt("Court1");
        assertTrue(courtBooking.isCourtAvailable("Court1"));
        assertThrows(IllegalStateException.class, () -> courtBooking.releaseCourt("Court1"));
        assertThrows(IllegalArgumentException.class, () -> courtBooking.releaseCourt("Court4"));
    }
}
