    public static void main(String[] args) {
        Robot robot = new Robot();

        // Añadir movimientos a la cola
        robot.addMovement(new Movement(Movement.DISPLACEMENT, 100));
        robot.addMovement(new Movement(Movement.ROTATION, 90));
        robot.addMovement(new Movement(Movement.DISPLACEMENT, -50));
        robot.addMovement(new Movement(Movement.ROTATION, -45));

        // Ejecutar movimientos
        while (robot.hasPendingMovements()) {
            robot.executeNextMovement();
        }
    }
}
```

### Explicación

