    private Node<E> next;

    // Constructor que no recibe información para inicializar ningún atributo
    public Node() {
        this.info = null;
        this.next = null;
    }

    // Constructor que permite inicializar el atributo info
    public Node(E info) {
        this.info = info;
        this.next = null;
    }

    // Constructor que permite inicializar los dos atributos
    public Node(E info, Node<E> next) {
        this.info = info;
        this.next = next;
    }

