    public E getInfo() {
        return info;
    }

    // Método set para el atributo info
    public void setInfo(E info) {
        this.info = info;
    }

    // Método get para el atributo next
    public Node<E> getNext() {
        return next;
    }

    // Método set para el atributo next
    public void setNext(Node<E> next) {
        this.next = next;
    }

    // Método main para probar todos los métodos desarrollados
    public static void main(String[] args) {
        // Prueba del constructor sin parámetros
        Node<Integer> node1 = new Node<>();
        System.out.println("Node1 info: " + node1.getInfo()); // Debe ser null
        System.out.println("Node1 next: " + node1.getNext()); // Debe ser null

        // Prueba del constructor con el atributo info
        Node<Integer> node2 = new Node<>(5);
        System.out.println("Node2 info: " + node2.getInfo()); // Debe ser 5
        System.out.println("Node2 next: " + node2.getNext()); // Debe ser null

