import java.util.ArrayList;

// Definición de la interfaz Mobile
public interface Mobile {
    public static final double acceptancePersonal = 4;
    public static final double acceptanceEnterprise = 7;
    public static final double acceptancePhoto = 10;

    double estimatePrice(double estimatedSells);
}

// Clase EnterpriseMobilePhone que implementa la interfaz Mobile
class EnterpriseMobilePhone implements Mobile {
    private String owner;
    private int phoneNumber;
    private String enterpriseId;

    public EnterpriseMobilePhone(String owner, int phoneNumber, String enterpriseId) {
        this.owner = owner;
        this.phoneNumber = phoneNumber;
        this.enterpriseId = enterpriseId;
    }

    @Override
    public double estimatePrice(double estimatedSells) {
        return Mobile.acceptanceEnterprise * estimatedSells;
    }

    @Override
    public String toString() {
        return "EnterpriseMobilePhone [owner=" + owner + ", phoneNumber=" + phoneNumber + ", enterpriseId=" + enterpriseId + "]";
    }
}

// Clase PersonalMobilePhone que implementa la interfaz Mobile
class PersonalMobilePhone implements Mobile {
    private String owner;
    private int phoneNumber;
    private String operatingSystem;

    public PersonalMobilePhone(String owner, int phoneNumber, String operatingSystem) {
        this.owner = owner;
        this.phoneNumber = phoneNumber;
        this.operatingSystem = operatingSystem;
    }

    @Override
    public double estimatePrice(double estimatedSells) {
        return Mobile.acceptancePersonal * estimatedSells;
    }

    @Override
    public String toString() {
        return "PersonalMobilePhone [owner=" + owner + ", phoneNumber=" + phoneNumber + ", operatingSystem=" + operatingSystem + "]";
    }
}

// Clase PhotoMobilePhone que implementa la interfaz Mobile
class PhotoMobilePhone implements Mobile {
    private String owner;
    private int phoneNumber;
    private int definition;

    public PhotoMobilePhone(String owner, int phoneNumber, int definition) {
        this.owner = owner;
        this.phoneNumber = phoneNumber;
        this.definition = definition;
    }

    @Override
    public double estimatePrice(double estimatedSells) {
        return definition * Mobile.acceptancePhoto * estimatedSells;
    }

    @Override
    public String toString() {
        return "PhotoMobilePhone [owner=" + owner + ", phoneNumber=" + phoneNumber + ", definition=" + definition + "]";
    }
}

// Clase principal para probar las implementaciones
public class MainMethodMobiles {
    public static void main(String[] args) {
        // Crear instancias de cada tipo de móvil
        EnterpriseMobilePhone enterprise = new EnterpriseMobilePhone("Paco", 67878798, "ID10078978A");
        PersonalMobilePhone personal = new PersonalMobilePhone("Adrian", 67878798, "MacOS");
        PhotoMobilePhone photo = new PhotoMobilePhone("Pepe", 797987898, 1920);

        // Crear un ArrayList para almacenar los objetos
        ArrayList<Mobile> mobiles = new ArrayList<>();
        mobiles.add(enterprise);
        mobiles.add(personal);
        mobiles.add(photo);

        // Recorrer el ArrayList y imprimir la información de cada objeto
        for (Mobile mobile : mobiles) {
            System.out.println(mobile.toString());
        }
    }
}
```

### Explicación

1. **Definición de la Interfaz `Mobile`**:
   - Define las constantes y el método `estimatePrice(double estimatedSells)`.

2. **Clases que Implementan `Mobile`**:
   - `EnterpriseMobilePhone`, `PersonalMobilePhone`, y `PhotoMobilePhone` implementan la interfaz `Mobile`.
   - Cada clase tiene su propio constructor y sobrescribe el método `estimatePrice`.
