        this.year = year;
    }

    public int getYear() {
        return year;
    }
}

public class FindOldestBook {
    public static void main(String[] args) {
        ArrayList<Book> books = new ArrayList<>();
        books.add(new Book("Book A", 1990));
        books.add(new Book("Book B", 1985));
        books.add(new Book("Book C", 2000));
        books.add(new Book("Book D", 1975));
        books.add(new Book("Book E", 2010));

        // Inicializamos oldestYear con el valor máximo posible para un entero
        int oldestYear = Integer.MAX_VALUE;

        // Iteramos sobre cada libro en la lista
        for (Book book : books) {
            // Comparamos el año de publicación del libro con oldestYear
            if (book.getYear() < oldestYear) {
                // Si el año de publicación del libro es menor, actualizamos oldestYear
                oldestYear = book.getYear();
            }
        }

        // Al final, oldestYear contendrá el año de publicación más antiguo
        System.out.println("The oldest year of publication is: " + oldestYear);
    }
}
```

**Subrayando lo importante**:
- **Inicialización**: `oldestYear` se establece en `Integer.MAX_VALUE` para asegurar que cualquier año de publicación será menor al valor inicial.
- **Comparación**: Se compara el año de cada libro con `oldestYear` y se actualiza si se encuentra un año menor.
- **Resultado**: `oldestYear` contendrá el **menor año de publicación** entre todos los libros, es decir, el año de publicación más antiguo.

