### Clase `Triangle`

```java
import java.awt.Point;

public class Triangle extends Figure {
    private Point vertex1, vertex2, vertex3;

    // Constructor
    public Triangle(String name, Point vertex1, Point vertex2, Point vertex3) {
        super(name);
        this.vertex1 = vertex1;
        this.vertex2 = vertex2;
        this.vertex3 = vertex3;
    }

    // Implementa el método area()
    @Override
    public double area() {
        return 0.5 * Math.abs(vertex1.getX() * (vertex2.getY() - vertex3.getY()) +
                              vertex2.getX() * (vertex3.getY() - vertex1.getY()) +
                              vertex3.getX() * (vertex1.getY() - vertex2.getY()));
    }

    // Implementa el método isRegular()
    @Override
    public boolean isRegular() {
        double side1 = vertex1.distance(vertex2);
        double side2 = vertex2.distance(vertex3);
        double side3 = vertex3.distance(vertex1);
        return side1 == side2 && side2 == side3;
    }

    // Sobreescribe el método toString()
    @Override
    public String toString() {
        return getName() + " [vertex1=" + vertex1 + ", vertex2=" + vertex2 + ", vertex3=" + vertex3 + "]";
    }

    // Métodos get y set
    public Point getVertex1() {
        return vertex1;
    }

    public void setVertex1(Point vertex1) {
        this.vertex1 = vertex1;
    }

    public Point getVertex2() {
        return vertex2;
    }

    public void setVertex2(Point vertex2) {
        this.vertex2 = vertex2;
    }

    public Point getVertex3() {
        return vertex3;
    }

    public void setVertex3(Point vertex3) {
        this.vertex3 = vertex3;
    }
}
```

### Clase `Quadrilateral`

```java
import java.awt.Point;

public abstract class Quadrilateral extends Figure {
    private Point vertex1, vertex2, vertex3, vertex4;

    // Constructor
    public Quadrilateral(String name, Point vertex1, Point vertex2, Point vertex3, Point vertex4) {
        super(name);
        this.vertex1 = vertex1;
        this.vertex2 = vertex2;
        this.vertex3 = vertex3;
        this.vertex4 = vertex4;
    }

    // Implementa el método isRegular()
    @Override
    public boolean isRegular() {
        return checkRectangle(vertex1, vertex2, vertex3, vertex4);
    }

    // Sobreescribe el método toString()
    @Override
    public String toString() {
        return getName() + " [vertex1=" + vertex1 + ", vertex2=" + vertex2 + ", vertex3=" + vertex3 + ", vertex4=" + vertex4 + "]";
    }

    // Métodos get y set
    public Point getVertex1() {
        return vertex1;
    }

    public void setVertex1(Point vertex1) {
        this.vertex1 = vertex1;
    }

    public Point getVertex2() {
        return vertex2;
    }

    public void setVertex2(Point vertex2) {
        this.vertex2 = vertex2;
    }

    public Point getVertex3() {
        return vertex3;
    }

    public void setVertex3(Point vertex3) {
        this.vertex3 = vertex3;
    }

    public Point getVertex4() {
        return vertex4;
    }

    public void setVertex4(Point vertex4) {
        this.vertex4 = vertex4;
    }

    // Métodos privados
    private boolean checkRectangle(Point v1, Point v2, Point v3, Point v4) {
        Point auxVertex = v1.nearest(new Point[]{v2, v3, v4});
        if (auxVertex.equals(v2)) {
            return v1.distance(v3) == v2.distance(v4)
                    && v1.distance(v4) == v2.distance(v3)
                    && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v3, v4}));
        } else if (auxVertex.equals(v3)) {
            return v1.distance(v2) == v3.distance(v4)
                    && v1.distance(v4) == v3.distance(v2)
                    && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v2, v4}));
        } else if (auxVertex.equals(v4)) {
            return v1.distance(v2) == v4.distance(v3)
                    && v1.distance(v3) == v4.distance(v2)
                    && scalarProduct(v1, auxVertex, v1.nearest(new Point[]{v2, v3}));
        } else {
            return false;
        }
    }

    private boolean scalarProduct(Point p1, Point p2, Point p3) {
        return (p3.getY() - p1.getY()) * (p2.getY() - p1.getY())
                + (p3.getX() - p1.getX()) * (p2.getX() - p1.getX()) == 0;
    }
}
```

### Clase `Rectangle`

```java
import java.awt.Point;

public class Rectangle extends Quadrilateral {

    // Constructor
    public Rectangle(String name, Point vertex1, Point vertex2, Point vertex3, Point vertex4) throws Exception {
        super(name, vertex1, vertex2, vertex3, vertex4);
        if (!isRegular()) {
            throw new Exception("The provided vertices do not form a regular rectangle.");
        }
    }

    // Implementa el método area()
    @Override
    public double area() {
        Point[] vertices = {getVertex1(), getVertex2(), getVertex3(), getVertex4()};
        Point v1 = getVertex1();
        Point v2 = v1.nearest(vertices);
        Point v3 = v1.nearest(new Point[]{vertices[0], vertices[1], vertices[2], vertices[3]});
        return v1.distance(v2) * v1.distance(v3);
    }

    // Sobreescribe el método toString()
    @Override
    public String toString() {
        return getName() + " [vertex1=" + getVertex1() + ", vertex2=" + getVertex2() + ", vertex3=" + getVertex3() + ", vertex4=" + getVertex4() + "]";
    }
}
```

### Clase `FiguresSet`

```java
import java.util.ArrayList;

public class FiguresSet {
    // Array of figures
    private ArrayList<Figure> figures;

    // Constructor of FiguresSet
    public FiguresSet() {
        figures = new ArrayList<>();
    }

    // Adds a new figure to the FigureSet
    public void addFigure(Figure f) {
        figures.add(f);
    }

    // Calculates the total area of the figures
    public double totalArea() {
        double total = 0;
        for (Figure f : figures) {
            total += f.area();
        }
        return total;
    }

    // figures to String
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Figure f : figures) {
            sb.append(f.toString()).append("\n");
        }
        return sb.toString();
    }

    // Main program
    public static void main(String args[]) throws Exception {
        FiguresSet set = new FiguresSet();

        // Crear un círculo
        Circle circle = new Circle("Circle", new Point(0, 0), 5);

        // Crear un triángulo
        Triangle triangle = new Triangle("Triangle", new Point(0, 0), new Point(4, 0), new Point(0, 3));

        // Crear un rectángulo
        Rectangle rectangle = new Rectangle("Rectangle", new Point(0, 0), new Point(4, 0), new Point(4, 3), new Point(0, 3));

        // Añadir las figuras al set
        set.addFigure(circle);
        set.addFigure(triangle);
        set.addFigure(rectangle);

        // Imprimir el resultado del cálculo del área total y la información de las figuras
        System.out.println("Total area: " + set.totalArea());
        System.out.println("Figures:\n" + set.toString());
    }
}
```

