import java.util.ArrayList;

public class FiguresSet {
    // Array of figures
    private ArrayList<Figure> figures;

    // Constructor of FiguresSet
    public FiguresSet() {
        figures = new ArrayList<>();
    }

    // Adds a new figure to the FigureSet
    public void addFigure(Figure f) {
        figures.add(f);
    }

    // Calculates the total area of the figures
    public double totalArea() {
        double total = 0;
        for (Figure f : figures) {
            total += f.area();
        }
        return total;
    }

    // figures to String
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Figure f : figures) {
            sb.append(f.toString()).append("\n");
        }
        return sb.toString();
    }

    // Main program
    public static void main(String args[]) throws Exception {
        FiguresSet set = new FiguresSet();

        // Crear un círculo
        Circle circle = new Circle("Circle", new Point(0, 0), 5);

        // Crear un triángulo
        Triangle triangle = new Triangle("Triangle", new Point(0, 0), new Point(4, 0), new Point(0, 3));

        // Crear un rectángulo
