```java
public class Rectangle extends Quadrilateral {

    public Rectangle(String name, Point P1, Point P2, Point P3, Point P4) throws IllegalArgumentException {
        super(name, P1, P2, P3, P4);
        if (!checkRectangle(P1, P2, P3, P4)) {
            throw new IllegalArgumentException("The provided vertexes do not form a rectangle.");
        }
    }

    private boolean checkRectangle(Point P1, Point P2, Point P3, Point P4) {
        // Implementa la lógica para verificar si los puntos forman un rectángulo
        // Por ejemplo, puedes verificar que los lados opuestos sean iguales y los ángulos sean rectos
        // Aquí hay una implementación simple que puedes ajustar según tus necesidades
        double d1 = P1.distance(P2);
        double d2 = P2.distance(P3);
        double d3 = P3.distance(P4);
        double d4 = P4.distance(P1);
        double diag1 = P1.distance(P3);
        double diag2 = P2.distance(P4);

        return d1 == d3 && d2 == d4 && diag1 == diag2;
    }

    public double area() {
        double base = P1.distance(P2);
        double height = P2.distance(P3);
        return base * height;
    }

    public String toString(String name, Point P1, Point P2, Point P3, Point P4) {
        return ("I am a rectangle named " + name + ", and my vertexes are " + P1.toString(P1.getX(), P1.getY()) 
                + ", " + P2.toString(P2.getX(), P2.getY()) + ", " + P3.toString(P3.getX(), P3.getY())
                + " and " + P4.toString(P4.getX(), P4.getY()));
    }
}
```

