    @Test
    public void testDivisionWithException() {
        assertThrows(ArithmeticException.class, () -> {
            int a = 1 / 0;
        });
    }

    @Test
    public void testDivisionWithException2() {
        try {
            int i = 1 / 0;
            fail("Failed test");
        } catch (ArithmeticException e) {
            // Test passed
        }
    }

    @Test
