        // Inicializar el árbol de vuelos
        flights = new LBTree<>("Madrid");
        LBTree<String> paris = new LBTree<>("Paris");
        LBTree<String> berlin = new LBTree<>("Berlin");
        flights.insert(paris, BTree.LEFT);
        flights.insert(berlin, BTree.RIGHT);

        LBTree<String> brussels = new LBTree<>("Brussels");
        LBTree<String> hanoi = new LBTree<>("Hanoi");
        paris.insert(brussels, BTree.LEFT);
        brussels.insert(hanoi, BTree.RIGHT);

        LBTree<String> kiev = new LBTree<>("Kiev");
        hanoi.insert(kiev, BTree.RIGHT);

        LBTree<String> lima = new LBTree<>("Lima");
        LBTree<String> moscow = new LBTree<>("Moscow");
        berlin.insert(lima, BTree.LEFT);
        berlin.insert(moscow, BTree.RIGHT);

        LBTree<String> prague = new LBTree<>("Prague");
        LBTree<String> seoul = new LBTree<>("Seoul");
        LBTree<String> taipei = new LBTree<>("Taipei");
        moscow.insert(prague, BTree.LEFT);
        prague.insert(seoul, BTree.LEFT);
        prague.insert(taipei, BTree.RIGHT);
    }

    public int getSize() {
        return flights.size();
    }

    public String getPreOrder() {
        return flights.toStringPreOrder();
    }

    public int getSubTreeSize(String root) throws BTreeException {
        BTree<String> subTree = findSubTree(flights, root);
        return subTree.size();
    }

    public String getSubTreePostOrder(String root) throws BTreeException {
        BTree<String> subTree = findSubTree(flights, root);
        return subTree.toStringPostOrder();
    }

    private BTree<String> findSubTree(BTree<String> tree, String root) throws BTreeException {
        if (tree.isEmpty()) {
            return null;
        }
        if (tree.getInfo().equals(root)) {
            return tree;
        }
        BTree<String> left = findSubTree(tree.getLeft(), root);
        if (left != null) {
            return left;
        }
        return findSubTree(tree.getRight(), root);
    }

    public static void main(String[] args) {
        try {
            // Crear la instancia del gestor de vuelos
            FlightManager manager = new FlightManager();

            // Imprimir el tamaño del árbol cuya raíz es Madrid
