### Sección 7: Cálculo del punto más cercano

```java
public class Point {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public double distance() {
        return Math.sqrt(x * x + y * y);
    }

    public double distance(Point anotherPoint) {
        double dx = x - anotherPoint.getX();
        double dy = y - anotherPoint.getY();
        return Math.sqrt(dx * dx + dy * dy);
    }

    public int quadrant() {
        if (x == 0 || y == 0) {
            return 0;
        } else if (x > 0 && y > 0) {
            return 1;
        } else if (x < 0 && y > 0) {
            return 2;
        } else if (x < 0 && y < 0) {
            return 3;
        } else {
            return 4;
        }
    }

    public Point nearest(Point[] otherPoints) {
        if (otherPoints == null || otherPoints.length == 0) {
            return null;
        }

        Point nearestPoint = otherPoints[0];
        double nearestDistance = distance(nearestPoint);

        for (Point point : otherPoints) {
            double currentDistance = distance(point);
            if (currentDistance < nearestDistance) {
                nearestPoint = point;
                nearestDistance = currentDistance;
            }
        }

        return nearestPoint;
    }
}
```

