            System.out.println("Coordenada y: " + point.getY());
            System.out.println("Distancia al origen: " + point.distance());

            // Crear otro punto para probar la distancia entre dos puntos
            Point anotherPoint = new Point(3, 4);
            System.out.println("Distancia a otro punto (3, 4): " + point.distance(anotherPoint));

            // Verificar el cuadrante
            System.out.println("Cuadrante: " + point.quadrant());

            // Crear un array de puntos para probar el punto más cercano
            Point[] points = {new Point(1, 1), new Point(2, 2), new Point(3, 3)};
            Point nearestPoint = point.nearest(points);
            System.out.println("Punto más cercano: " + nearestPoint);
        } catch (NumberFormatException e) {
            System.out.println("Los argumentos deben ser números reales.");
        }
    }
}
```

