        Point vertex2 = new Point(3, 0);
        Point vertex3 = new Point(0, 4);

        Triangle triangle = new Triangle(vertex1, vertex2, vertex3);
        double[] lengths = triangle.sideLengths();

        System.out.println("Longitudes de los lados del triángulo:");
        for (double length : lengths) {
            System.out.println(length);
        }
    }
}
