public class CandleCounterIterative implements CandleCounter {

    @Override
    public String getImplementationDescription() {
        return "Iterative";
    }

    @Override
    public long count(long years) {
        long totalCandles = 0;
        for (long i = 1; i <= years; i++) {
            totalCandles += i;
        }
        return totalCandles;
    }

    public static void main(String[] args) {
        CandleCounterIterative counter = new CandleCounterIterative();
        System.out.println("Implementation: " + counter.getImplementationDescription());
        System.out.println("Total candles for 6 years: " + counter.count(6));
    }
}
```

