```java
public class ArrayInsertion {

    public static void main(String[] args) {
        // Crear e inicializar el array con diez elementos, todos con el valor 1
        int[] originalArray = new int[10];
        for (int i = 0; i < originalArray.length; i++) {
            originalArray[i] = 1;
        }

        // Imprimir el array original
        System.out.print("Array original: ");
        for (int i : originalArray) {
            System.out.print(i + " ");
        }
        System.out.println();

        // Crear un nuevo array con un tamaño mayor para insertar el nuevo elemento
        int[] newArray = new int[11];

        // Copiar los elementos del array original al nuevo array, insertando el valor 0 en la cuarta posición
        for (int i = 0, j = 0; i < newArray.length; i++) {
            if (i == 3) {
                newArray[i] = 0; // Insertar el valor 0 en la cuarta posición
            } else {
                newArray[i] = originalArray[j];
                j++;
            }
        }

        // Imprimir el nuevo array
        System.out.print("Nuevo array: ");
        for (int i : newArray) {
            System.out.print(i + " ");
        }
    }
}
```

