public class LBSTree<E> implements BSTree<E> {
    private LBSNode<E> root;

    // Constructor para crear un árbol vacío
    public LBSTree() {
        root = null;
    }

    // Constructor para crear un árbol con un solo nodo
    public LBSTree(Comparable key, E info) {
        root = new LBSNode<E>(key, info, new LBSTree<E>(), new LBSTree<E>());
    }

    @Override
    public boolean isEmpty() {
        return root == null;
    }

    @Override
    public E getInfo() {
        if (root == null) {
            return null;
        }
        return root.getInfo();
    }

    @Override
    public Comparable getKey() {
        if (root == null) {
            return null;
        }
        return root.getKey();
    }

    @Override
    public BSTree<E> getLeft() {
        if (root == null) {
            return null;
        }
        return root.getLeft();
    }

    @Override
    public BSTree<E> getRight() {
        if (root == null) {
            return null;
        }
        return root.getRight();
    }

    @Override
    public String toStringPreOrder() {
        if (root == null) {
            return "";
        }
        return root.getKey() + " " + root.getLeft().toStringPreOrder() + root.getRight().toStringPreOrder();
    }

    @Override
    public String toStringInOrder() {
        if (root == null) {
            return "";
        }
        return root.getLeft().toStringInOrder() + root.getKey() + " " + root.getRight().toStringInOrder();
    }

    @Override
    public String toStringPostOrder() {
        if (root == null) {
            return "";
        }
        return root.getLeft().toStringPostOrder() + root.getRight().toStringPostOrder() + root.getKey() + " ";
    }

    @Override
    public String toString() {
        return toStringPreOrder();
    }

    @Override
    public void insert(Comparable key, E info) {
        root = insertRec(root, key, info);
    }

    private LBSNode<E> insertRec(LBSNode<E> node, Comparable key, E info) {
        if (node == null) {
            return new LBSNode<E>(key, info, new LBSTree<E>(), new LBSTree<E>());
        }

        if (key.compareTo(node.getKey()) < 0) {
            node.setLeft(insertRec((LBSNode<E>) node.getLeft().getRoot(), key, info));
        } else if (key.compareTo(node.getKey()) > 0) {
            node.setRight(insertRec((LBSNode<E>) node.getRight().getRoot(), key, info));
        } else {
            node.setInfo(info);
        }

        return node;
    }

    @Override
    public BSTree<E> search(Comparable key) {
        return searchRec(root, key);
    }

    private BSTree<E> searchRec(LBSNode<E> node, Comparable key) {
        if (node == null || key.compareTo(node.getKey()) == 0) {
            return node == null ? null : new LBSTree<E>(node.getKey(), node.getInfo());
        }

        if (key.compareTo(node.getKey()) < 0) {
            return searchRec((LBSNode<E>) node.getLeft().getRoot(), key);
        } else {
            return searchRec((LBSNode<E>) node.getRight().getRoot(), key);
        }
    }

    public LBSNode<E> getRoot() {
        return root;
    }
}
