```java
public abstract class Quadrilateral extends Figure {
    private Point[] vertices;

    // Constructor of the Quadrilateral class
    public Quadrilateral(String name, Point[] vertices) {
        super(name);
        this.vertices = vertices;
    }

    // Abstract method to calculate the area
    @Override
    abstract public double area();

    // Method to check if the quadrilateral is regular
    @Override
    public boolean isRegular() {
        // Implement the logic to check if the quadrilateral is regular
        return isRectangle();
    }

    // Method to check if the quadrilateral is a rectangle
    private boolean isRectangle() {
        // Assuming vertices are in order: A, B, C, D
        Point A = vertices[0];
        Point B = vertices[1];
        Point C = vertices[2];
        Point D = vertices[3];

        // Calculate the distances between the points
        double AB = distance(A, B);
        double BC = distance(B, C);
        double CD = distance(C, D);
        double DA = distance(D, A);
        double AC = distance(A, C);
        double BD = distance(B, D);

        // Check if opposite sides are equal and diagonals are equal
        return (AB == CD && BC == DA && AC == BD);
    }

    // Helper method to calculate the distance between two points
    private double distance(Point p1, Point p2) {
        return Math.sqrt(Math.pow(p2.getX() - p1.getX(), 2) + Math.pow(p2.getY() - p1.getY(), 2));
    }

    // Gets the vertices of the quadrilateral
    public Point[] getVertices() {
        return vertices;
    }

    // Sets the vertices of the quadrilateral
    public void setVertices(Point[] vertices) {
        this.vertices = vertices;
    }
}
```

