### Clase Quadrilateral

```java
import java.awt.Point;

public abstract class Quadrilateral extends Figure {
    private Point vertex1;
    private Point vertex2;
    private Point vertex3;
    private Point vertex4;

    // Constructor
    public Quadrilateral(String name, Point vertex1, Point vertex2, Point vertex3, Point vertex4) {
        super(name);
        this.vertex1 = vertex1;
        this.vertex2 = vertex2;
        this.vertex3 = vertex3;
        this.vertex4 = vertex4;
    }

    // Implementa el método isRegular() que indique si el cuadrilátero es regular
    @Override
    public boolean isRegular() {
        return checkRectangle();
    }

    // Método privado checkRectangle() que verifica si el cuadrilátero es un rectángulo o un cuadrado
    private boolean checkRectangle() {
        double d1 = vertex1.distance(vertex2);
        double d2 = vertex2.distance(vertex3);
        double d3 = vertex3.distance(vertex4);
        double d4 = vertex4.distance(vertex1);
        double d5 = vertex1.distance(vertex3);
        double d6 = vertex2.distance(vertex4);

        return (d1 == d3 && d2 == d4 && scalarProduct(vertex1, vertex2, vertex3) == 0 && scalarProduct(vertex2, vertex3, vertex4) == 0);
    }

    // Método privado scalarProduct() que calcula el producto escalar de dos vectores
    private double scalarProduct(Point p1, Point p2, Point p3) {
        double v1x = p2.x - p1.x;
        double v1y = p2.y - p1.y;
        double v2x = p3.x - p2.x;
        double v2y = p3.y - p2.y;
        return v1x * v2x + v1y * v2y;
    }

    // Sobreescribe el método toString()
    @Override
    public String toString() {
        return "Quadrilateral[name=" + getName() + ", vertex1=" + vertex1 + ", vertex2=" + vertex2 + ", vertex3=" + vertex3 + ", vertex4=" + vertex4 + "]";
    }

