public class Point {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public String toString() {
        return "The quadrant is: " + quadrant() + " The Point is: " + "(" + getX() + ", " + getY() + ")";
    }

