```java
import java.util.Scanner;

public class CountWords {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Pedir al usuario el String
        System.out.print("Introduce un String: ");
        String userInput = scanner.nextLine();

        // Contar el número de palabras en el String
        int wordCount = countWords(userInput);

        // Imprimir el número de palabras
        System.out.println("El número de palabras en el String es: " + wordCount);

        scanner.close();
    }

    // Método para contar el número de palabras en un String
    public static int countWords(String str) {
        if (str == null || str.isEmpty()) {
            return 0;
        }

        // Dividir el String en palabras usando espacios como delimitadores
        String[] words = str.trim().split("\\s+");
        return words.length;
    }
}
```

