import java.util.Scanner;

class ComplexNumber {
    private double real;
    private double imaginary;

    public ComplexNumber(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    public double getReal() {
        return real;
    }

    public double getImaginary() {
        return imaginary;
    }

    public ComplexNumber add(ComplexNumber other) {
        double newReal = this.real + other.real;
        double newImaginary = this.imaginary + other.imaginary;
        return new ComplexNumber(newReal, newImaginary);
    }

    @Override
    public String toString() {
        return real + " + " + imaginary + "i";
    }
}

public class AddComplexNumbers {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Pedir al usuario el primer número complejo
        System.out.print("Introduce la parte real del primer número complejo: ");
        double real1 = scanner.nextDouble();
        System.out.print("Introduce la parte imaginaria del primer número complejo: ");
        double imaginary1 = scanner.nextDouble();
        ComplexNumber complex1 = new ComplexNumber(real1, imaginary1);

        // Pedir al usuario el segundo número complejo
        System.out.print("Introduce la parte real del segundo número complejo: ");
        double real2 = scanner.nextDouble();
        System.out.print("Introduce la parte imaginaria del segundo número complejo: ");
        double imaginary2 = scanner.nextDouble();
        ComplexNumber complex2 = new ComplexNumber(real2, imaginary2);

        // Sumar los dos números complejos
        ComplexNumber sum = complex1.add(complex2);

        // Imprimir el resultado
        System.out.println("La suma de los dos números complejos es: " + sum);

        scanner.close();
    }
}
```

